#semantic C9E1f_fog.decal
#semantic C9E1f_fog.fogColor
#var float2 texCoord : $vin.TEXCOORD0 : TEX0 : 0 : 1
#var float fogExponent : $vin.TEXCOORD1 : TEX1 : 1 : 1
#var float4 color : $vin.COLOR : COL0 : 2 : 1
#var float4 oColor : $vout.COLOR : COL : 3 : 1
#var sampler2D decal :  : texunit 0 : 4 : 1
#var float3 fogColor :  : c[0] : 5 : 1
PARAM c[1] = { program.local[0] };
TEMP R0;
TEX R0.xyz, fragment.texcoord[0], texture[0], 2D;
ABS R0.w, fragment.texcoord[1].x;
MAD R0.xyz, fragment.color.primary, R0, -c[0];
EX2 R0.w, -R0.w;
MAD result.color.xyz, R0.w, R0, c[0];
MOV result.color.w, fragment.color.primary;
END
